@app.post("/v1/chat/completions", response_model=ChatCompletionResponse)
async def chat_completions(request: ChatCompletionRequest):
    """Generate a chat completion (OpenAI-compatible).

    Supports both text-only models (via mlx-lm) and vision-language models
    (via mlx-vlm, e.g. gemma-4).  The backend is auto-detected when the
    model is first loaded.
    """
    model_id = request.model or DEFAULT_CHAT_MODEL
    if not model_id:
        raise HTTPException(status_code=400, detail="No model specified")

    try:
        logger.info("Loading chat model: %s", model_id)
        backend, model, tokenizer = await run_mlx(registry.get_chat_model, model_id)
        logger.info("Chat model ready: %s (backend=%s)", model_id, backend.value)
    except Exception as e:
        logger.error("Failed to load chat model %s: %s", model_id, e)
        raise HTTPException(status_code=500, detail=f"Failed to load model: {e}")

    messages = [{"role": m.role, "content": m.content} for m in request.messages]
    max_tokens = request.max_tokens or 512
    temp = request.temperature if request.temperature is not None else 0.0

    logger.info(
        "Generating: model=%s, backend=%s, messages=%d, max_tokens=%d, temp=%.2f",
        model_id,
        backend.value,
        len(messages),
        max_tokens,
        temp,
    )
    t0 = time.perf_counter()

    try:
        if backend == ChatBackend.MLX_LM:
            (
                text,
                prompt_tokens,
                completion_tokens,
                finish_reason,
            ) = await run_mlx(
                _generate_mlx_lm,
                model,
                tokenizer,
                messages,
                max_tokens,
                temp,
                model_id,
            )
        else:
            (
                text,
                prompt_tokens,
                completion_tokens,
                finish_reason,
            ) = await run_mlx(
                _generate_mlx_vlm, model, tokenizer, messages, max_tokens, temp
            )
    except Exception as e:
        logger.error("Generation failed for %s: %s", model_id, e, exc_info=True)
        raise HTTPException(status_code=500, detail=f"Generation failed: {e}")

    elapsed = time.perf_counter() - t0
    tps = completion_tokens / elapsed if elapsed > 0 else 0
    logger.info(
        "Generation complete: %d prompt + %d completion tokens, %.2fs (%.1f tok/s)",
        prompt_tokens,
        completion_tokens,
        elapsed,
        tps,
    )

    return ChatCompletionResponse(
        choices=[
            ChatChoice(
                message=ChatChoiceMessage(content=text),
                finish_reason=finish_reason,
            )
        ],
        model=model_id,
        usage=ChatUsage(
            prompt_tokens=prompt_tokens,
            completion_tokens=completion_tokens,
            total_tokens=prompt_tokens + completion_tokens,
        ),
    )


# Texts per forward pass on the mlx-vlm path. A batch is padded to its longest
# text, so this bounds memory when a request carries many or long texts.
_EMBED_BATCH_SIZE = 32

def _generate_mlx_lm(
    model,
    tokenizer,
    messages: list[dict],
    max_tokens: int,
    temp: float,
    model_id: str,
) -> tuple[str, int, int, str]:
    """Generate text using mlx-lm (text-only LLMs). Runs on the MLX thread."""
    from mlx_lm import generate
    from mlx_lm.sample_utils import make_sampler

    prompt = tokenizer.apply_chat_template(
        messages,
        tokenize=False,
        add_generation_prompt=True,
        enable_thinking=False,
    )
    sampler = make_sampler(temp=temp)
    generate_kwargs = {
        "prompt": prompt,
        "max_tokens": max_tokens,
        "sampler": sampler,
    }
    prompt_cache = _maybe_build_optiq_prompt_cache(model, model_id)
    if prompt_cache is not None:
        generate_kwargs["prompt_cache"] = prompt_cache

    generate_fn = cast(Any, generate)
    text = generate_fn(model, tokenizer, **generate_kwargs)

    text = _strip_thinking(text)
    prompt_tokens = len(tokenizer.encode(prompt))
    completion_tokens = len(tokenizer.encode(text))
    return (
        text,
        prompt_tokens,
        completion_tokens,
        _infer_finish_reason(completion_tokens, max_tokens),
    )


def _generate_mlx_vlm(
    model, processor, messages: list[dict], max_tokens: int, temp: float
) -> tuple[str, int, int, str]:
    """Generate text using mlx-vlm (vision-language models). Runs on the MLX thread."""
    from mlx_vlm import generate
    from mlx_vlm.prompt_utils import apply_chat_template

    prompt = cast(
        str,
        apply_chat_template(processor, model.config, messages, enable_thinking=False),
    )

    result = generate(
        model,
        processor,
        prompt,
        max_tokens=max_tokens,
        temperature=temp,
        enable_thinking=False,
    )

    text = _strip_thinking(result.text)
    return (
        text,
        result.prompt_tokens,
        result.generation_tokens,
        _infer_finish_reason(result.generation_tokens, max_tokens),
    )


def _infer_finish_reason(completion_tokens: int, max_tokens: int) -> str:
    """Best-effort OpenAI-style finish reason for MLX backends."""
    if completion_tokens >= max_tokens:
        return "length"
    return "stop"
def _strip_thinking(text: str) -> str:
    """Remove reasoning/thinking blocks from generated text.

    Handles multiple formats:
    - <think>...</think> (Qwen, DeepSeek)
    - <channel|>...<|channel> and <|channel>...<channel|> (Gemma 4)
    """
    import re

    # <think>...</think> — greedy within blocks, DOTALL for multiline
    text = re.sub(r"<think>.*?</think>", "", text, flags=re.DOTALL)
    # Unclosed <think> at the start — strip everything from <think> onward
    if "<think>" in text:
        text = text[: text.index("<think>")]
    text = _strip_gemma_channel_blocks(text)
    return text.strip()


def _strip_gemma_channel_blocks(text: str) -> str:
    """Strip Gemma 4 reasoning blocks in either channel-token order."""
    result: list[str] = []
    rest = text

    while True:
        normal = rest.find("<channel|>")
        reversed_ = rest.find("<|channel>")

        if normal == -1 and reversed_ == -1:
            break

        if normal != -1 and (reversed_ == -1 or normal <= reversed_):
            start, open_tag, close_tag = normal, "<channel|>", "<|channel>"
        else:
            start, open_tag, close_tag = reversed_, "<|channel>", "<channel|>"

        result.append(rest[:start])
        rest = rest[start + len(open_tag) :]

        end = rest.find(close_tag)
        if end == -1:
            return "".join(result)
        rest = rest[end + len(close_tag) :]

    result.append(rest)
    return "".join(result)


    def get_chat_model(self, model_id: str) -> tuple[ChatBackend, Any, Any]:
        """Return (backend, model, tokenizer/processor) for a chat model.

        Tries mlx_lm first (text-only LLMs). If the model architecture is
        unsupported, falls back to mlx_vlm (vision-language models like gemma-4).
        """
        if model_id not in self._chat_models:
            try:
                from mlx_lm import load

                logger.info("Trying mlx_lm for: %s", model_id)
                loaded = load(model_id, lazy=True)
                model = loaded[0]
                tokenizer = loaded[1]
                self._chat_models[model_id] = (ChatBackend.MLX_LM, model, tokenizer)
                logger.info("Loaded %s via mlx_lm", model_id)
            except (ValueError, KeyError) as exc:
                # Architecture not supported by mlx_lm — try mlx_vlm
                logger.info(
                    "mlx_lm unsupported for %s (%s), falling back to mlx_vlm",
                    model_id,
                    exc,
                )
                from mlx_vlm import load

                model, processor = load(model_id)
                self._chat_models[model_id] = (ChatBackend.MLX_VLM, model, processor)
                logger.info("Loaded %s via mlx_vlm", model_id)
        return self._chat_models[model_id]

