"""Model loading and generation must share one thread.

Since MLX 0.32, a lazy array built on one thread cannot be evaluated on another
("There is no Stream(gpu, 0) in current thread"). Gemma 4 hits this through its
RoPE frequencies, which are computed lazily at load time and first evaluated
during generation. These tests fake the model and mlx-lm's generate, but use
real MLX arrays, so on MLX >= 0.32 they fail if the server ever loads and
generates on different threads.
"""

import threading

import pytest

mx = pytest.importorskip("mlx.core")
mlx_lm = pytest.importorskip("mlx_lm")

from fastapi.testclient import TestClient  # noqa: E402

import server  # noqa: E402
from registry import ChatBackend  # noqa: E402


class FakeTokenizer:
    def apply_chat_template(self, messages, **kwargs):
        return " ".join(m["content"] for m in messages)

    def encode(self, text):
        return text.split()


class FakeModel:
    def __init__(self):
        # Lazy and not a parameter, like Gemma 4's RoPE `_freqs`.
        self.freqs = mx.exp(mx.arange(8, dtype=mx.float32) * 0.1)
        self.load_thread = threading.get_ident()


@pytest.fixture
def fake_chat(monkeypatch):
    seen = {}

    def get_chat_model(model_id):
        model = FakeModel()
        seen["load"] = model.load_thread
        return ChatBackend.MLX_LM, model, FakeTokenizer()

    def generate(model, tokenizer, prompt, **kwargs):
        seen["generate"] = threading.get_ident()
        mx.eval(model.freqs)  # raises across threads on MLX >= 0.32
        return "topic label"

    monkeypatch.setattr(server.registry, "default_model", None)
    monkeypatch.setattr(server.registry, "get_chat_model", get_chat_model)
    monkeypatch.setattr(mlx_lm, "generate", generate)
    return seen


def test_chat_loads_and_generates_on_the_mlx_thread(fake_chat):
    with TestClient(server.app) as client:
        response = client.post(
            "/v1/chat/completions",
            json={
                "model": "fake/model",
                "messages": [{"role": "user", "content": "label these"}],
                "max_tokens": 8,
            },
        )
    assert response.status_code == 200, response.json()
    assert response.json()["choices"][0]["message"]["content"] == "topic label"
    assert fake_chat["load"] == fake_chat["generate"]
    assert fake_chat["load"] != threading.get_ident()  # off the caller's thread


def test_preloaded_model_survives_a_lifespan_restart(monkeypatch):
    # The lifespan preloads the default embedding model. If it is cached across
    # a restart, its lazy arrays (built on the old MLX thread, never evaluated)
    # are evaluated on the new one. Patch the loader, not the registry, so the
    # registry's own cache is exercised.
    mlx_embeddings = pytest.importorskip("mlx_embeddings")
    from types import SimpleNamespace

    loads = []

    def load(model_id, **kwargs):
        model = FakeModel()
        loads.append(model.load_thread)
        return model, FakeTokenizer()

    def generate(model, tokenizer, texts, **kwargs):
        mx.eval(model.freqs)  # may raise across threads on MLX >= 0.32
        return SimpleNamespace(text_embeds=mx.ones((len(texts), 4)))

    monkeypatch.setattr(server.registry, "default_model", "fake/embedder")
    monkeypatch.setattr(mlx_embeddings, "load", load)
    monkeypatch.setattr(mlx_embeddings, "generate", generate)

    with TestClient(server.app):
        pass  # preload only; the model's lazy arrays stay unevaluated
    with TestClient(server.app) as client:
        response = client.post(
            "/v1/embeddings", json={"model": "fake/embedder", "input": ["a", "b"]}
        )
    assert response.status_code == 200, response.json()
    assert len(response.json()["data"]) == 2
    assert len(loads) == 2  # reloaded on the new lifespan's MLX thread


@pytest.mark.asyncio
async def test_run_mlx_keeps_lazy_arrays_usable_across_calls():
    lazy = await server.run_mlx(lambda: mx.arange(4) * 2)
    total = await server.run_mlx(lambda: (mx.eval(lazy), lazy.sum().item())[1])
    assert total == 12
# mlx-server

Local MLX server exposing OpenAI-compatible REST endpoints for text embeddings, multimodal embeddings, and chat completions. Runs on Apple Silicon via `mlx-embeddings`, `mlx-vlm`, and `mlx-lm`. Designed to be launched manually or spawned by xplorertui.

## Running

```bash
cd mlx-server
uv run uvicorn server:app --host 127.0.0.1 --port 8678
```

Override the default model via environment variable:

```bash
MLX_DEFAULT_MODEL=mlx-community/Qwen3-Embedding-0.6B-mxfp8 uv run uvicorn server:app --host 127.0.0.1 --port 8678
```

The server pre-loads the default embedding model at startup. Chat and additional models are lazy-loaded on first request. The server does not read xplorertui's `config.toml`: a client that asks for a different embedding model gets it loaded on its first request, in addition to the pre-loaded default. To avoid loading (and downloading) a default you do not use, start the server with `MLX_DEFAULT_MODEL` set to the model the client asks for, or set it to an empty string to skip the pre-load.

## Endpoints

| Method | Path | Description |
|--------|------|-------------|
| POST | `/v1/embeddings` | Text embeddings (OpenAI-compatible) |
| POST | `/v1/embeddings/multimodal` | Text + image embeddings |
| POST | `/v1/chat/completions` | Chat completions (OpenAI-compatible) |
| GET | `/v1/models` | List loaded/available models |
| GET | `/health` | Health check |

Interactive API docs are available at `/docs` when the server is running.

## Configuration

| Environment Variable | Default | Description |
|---|---|---|
| `MLX_DEFAULT_MODEL` | `mlx-community/Qwen3-Embedding-0.6B-mxfp8` | Embedding model to pre-load at startup; empty to skip the pre-load |
| `MLX_DEFAULT_CHAT_MODEL` | `mlx-community/Qwen3.5-0.8B-OptiQ-4bit` | Chat model (lazy-loaded on first request) |
| `MLX_ALLOW_REMOTE_IMAGES` | unset | Opt in to public HTTPS image downloads; redirects and private addresses remain blocked |

The xplorertui Rust client connects to this server when `mlx_server_url` is set in `~/.config/xplorertui/config.toml`:

```toml
mlx_server_url = "http://localhost:8678"
mlx_embedding_model = "mlx-community/embeddinggemma-2-mxfp8"  # optional
mlx_chat_model = "mlx-community/Qwen3.5-0.8B-OptiQ-4bit"      # optional
```

## Embedding models

`mlx-community/Qwen3-Embedding-0.6B-mxfp8` is the default, used when nothing else is configured. `mlx-community/embeddinggemma-2-mxfp8` (EmbeddingGemma 2, 768 dimensions, about 1.2 GB) is the preferred model; select it as shown above and start the server with the same id:

```bash
MLX_DEFAULT_MODEL=mlx-community/embeddinggemma-2-mxfp8 uv run uvicorn server:app --host 127.0.0.1 --port 8678
```

`ModelRegistry.get_text_model` tries `mlx-embeddings` first and falls back to `mlx-vlm`'s embedding loader when the architecture is unsupported. EmbeddingGemma 2 (`model_type: embedding_gemma2`) takes the fallback. Notes for that path:

- Use an MLX conversion (`mlx-community/embeddinggemma-2-*`). `mxfp8` is the one tested here; loading `google/embeddinggemma-2` directly is untested.
- When the fallback is taken, `mlx-embeddings` logs `ERROR [root] Model type embedding_gemma2 not supported.` once. That is expected.
- Only the text encoder is loaded; the vision and audio towers are dropped at load. `/v1/embeddings/multimodal` does not support this model yet.

